"""Disposable browser fixture for release surfaces and actual project workflows."""
import json,sys,tempfile,threading
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from backend.server import Application,LumenServer
from playwright.sync_api import sync_playwright

def main():
 out=ROOT/'qa-output/055-ui';out.mkdir(exist_ok=True);results=[]
 with tempfile.TemporaryDirectory(prefix='zenit-055-ui-') as tmp:
  base=Path(tmp);ws=base/'project';ws.mkdir();(ws/'main.c').write_text('int main(void) {\n    int value = 42;\n    return value;\n}\n');(ws/'main.py').write_text('print(42)\n')
  app=Application(ROOT,ws,data_dir=base/'profile');app.workspace.trusted=True;app.features.studio.update({'onboarded':True});app.features.prefs.update({'general.locale':'es','general.showWelcome':False,'updates.automatic':False,'appearance.motion':True})
  server=LumenServer(0,app);threading.Thread(target=server.serve_forever,daemon=True).start()
  try:
   with sync_playwright() as pw:
    browser=pw.chromium.launch(channel='msedge',headless=True);page=browser.new_page(viewport={'width':1600,'height':1000});errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
    def inject(route):
     response=route.fetch();route.fulfill(response=response,body=response.text()+'\nwindow.__qa={get editor(){return editor},get platform(){return platformUI},get desktop(){return desktopUI},get workbench(){return workbenchUI},get dock(){return dock},openFile};')
    page.route('**/src/app.js',inject);page.goto(f'http://127.0.0.1:{server.server_port}');page.wait_for_function('window.lumen?.ready');page.evaluate('__qa.openFile("main.c")');page.wait_for_function('__qa.editor.current==="main.c"')
    page.evaluate('''window.qaDocs='**value** — signed integer\\n\\nDocumentation for the selected value.\\n\\n'.repeat(5);monaco.languages.registerHoverProvider('c',{provideHover:()=>({contents:[{value:window.qaDocs}]})});monaco.languages.registerCodeActionProvider('c',{providedCodeActionKinds:['source'],provideCodeActions:()=>({actions:[],dispose(){}})});''')
    for theme in ['day','dark','forest']:
     page.evaluate('(theme)=>__qa.platform.savePreference("appearance.theme",theme)',theme)
     page.evaluate('''__qa.editor.view.focus();__qa.editor.view.setPosition({lineNumber:2,column:9});__qa.editor.view.getAction('editor.action.sourceAction').run()''');page.wait_for_timeout(300)
     message=page.locator('.monaco-editor-overlaymessage .message:visible');message.wait_for()
     data=message.evaluate('(n)=>({bg:getComputedStyle(n).backgroundColor,opacity:getComputedStyle(n).opacity,width:n.getBoundingClientRect().width,height:n.getBoundingClientRect().height,radius:getComputedStyle(n).borderRadius})');assert '/ 0.65)' in data['bg'],data;assert data['opacity']=='1' and data['width']>=240 and data['height']>38,data
     page.screenshot(path=str(out/(theme+'-actions.png')));page.keyboard.press('Escape')
     page.evaluate("__qa.editor.view.getAction('editor.action.showHover').run()");page.wait_for_timeout(450)
     popup=page.locator('.monaco-hover:visible');data=popup.evaluate('(n)=>({bg:getComputedStyle(n).backgroundColor,box:n.getBoundingClientRect().toJSON()})');assert '/ 0.65)' in data['bg'],data;assert 250<data['box']['height']<651,data;assert data['box']['right']<1600 and data['box']['bottom']<1000,data
     page.screenshot(path=str(out/(theme+'-documentation.png')));page.keyboard.press('Escape');results.append(theme+' documentation and source-action notice')
    page.evaluate('__qa.platform.savePreference("appearance.theme","day")');page.evaluate('window.qaDocs="**value**\\n\\nShort documentation.";__qa.editor.view.getAction("editor.action.showHover").run()');page.wait_for_timeout(400);assert page.locator('.monaco-hover:visible').bounding_box()['height']<470;page.keyboard.press('Escape');results.append('documentation fits its content')
    page.evaluate('window.qaDocs="Documentation paragraph.\\n\\n".repeat(50);__qa.editor.view.getAction("editor.action.showHover").run()');page.wait_for_timeout(400);content=page.locator('.monaco-hover:visible .monaco-hover-content');before=content.evaluate('(n)=>({height:n.clientHeight,full:n.scrollHeight})');assert before['full']>before['height'];content.evaluate('(n)=>n.scrollTop=n.scrollHeight');assert content.evaluate('(n)=>n.scrollTop')>0;page.keyboard.press('Escape');results.append('long documentation stays readable within viewport')
    page.evaluate('window.qaDocs="";__qa.editor.view.setPosition({lineNumber:2,column:9});__qa.editor.view.getAction("editor.action.showHover").run()');page.wait_for_timeout(450);page.screenshot(path=str(out/'reference-final.png'));page.keyboard.press('Escape');page.evaluate('window.qaDocs="Function reference.";__qa.editor.view.focus();__qa.editor.view.setPosition({lineNumber:1,column:6});__qa.editor.view.getAction("editor.action.showHover").run()');page.wait_for_function('document.querySelector(".monaco-hover .code-reference-heading strong")?.textContent==="main"');page.locator('[data-reference-melody]:visible').click();assert 'main.c' in page.locator('#ai-input').input_value();page.keyboard.press('Escape');results.append('reference action prepares a docked Melody question')
    page.locator('.view-lines').first.click(button='right',position={'x':120,'y':30});menu=page.locator('.editor-context-menu:visible').first;menu.wait_for();assert '/ 0.65)' in menu.evaluate('(n)=>getComputedStyle(n).backgroundColor');page.screenshot(path=str(out/'context-menu.png'));page.keyboard.press('Escape');results.append('right-click menu material')
    page.evaluate('__qa.platform.settings("general")');page.locator('[data-platform="updates"]').click();page.locator('#update-channel').wait_for();page.select_option('#update-channel','stable');page.wait_for_function('__qa.platform.prefs["updates.channel"]==="stable"');page.evaluate('__qa.platform.settingsWrite');assert app.features.prefs.get('updates.channel')=='stable';results.append('Settings update entry and persisted channel')
    page.locator('#update-whats-new').click();page.locator('#release-project').wait_for();page.locator('#release-project').click();page.locator('[data-kit="c"]').wait_for();page.locator('#modal-backdrop').wait_for(state='hidden');assert not app.features.updates.welcome()['show'];page.wait_for_timeout(300);page.screenshot(path=str(out/'project-workflows.png'));results.append('release panel acknowledges and opens project workflows')
    assert page.locator('.project-kit-form').count()==1
    page.locator('[data-kit="python"]').click();assert page.locator('[data-kit="python"]').get_attribute('aria-pressed')=='true';assert page.locator('[data-kit-plan="python"]').count()==1;assert page.locator('#workflow-kit-folder').input_value()=='proyecto-python'
    page.locator('[data-kit="asm"]').click();assert 'NASM' in page.locator('.project-kit-detail').inner_text();page.locator('[data-kit="c"]').click()
    page.set_viewport_size({'width':1280,'height':900});page.wait_for_timeout(300);assert page.locator('.project-workflows').evaluate('(n)=>n.scrollWidth<=n.clientWidth');assert page.locator('.project-language-list').evaluate('(n)=>n.scrollWidth<=n.clientWidth');page.screenshot(path=str(out/'project-workflows-compact.png'));page.set_viewport_size({'width':1600,'height':1000});results.append('single language configuration stays aligned in a smaller window')
    page.evaluate('__qa.editor.models.get("main.c").model.setValue("int main(void) { return 43; }\\n")');page.evaluate('__qa.desktop.handle("project-workflows")');page.locator('#workflow-save').wait_for();assert 'Cambios sin guardar' in page.locator('.project-file-identity').inner_text();assert '43' not in (ws/'main.c').read_text();page.locator('#workflow-save').click();page.locator('#workflow-save').wait_for(state='detached');assert '43' in (ws/'main.c').read_text();assert 'Archivo guardado' in page.locator('.project-file-identity').inner_text();results.append('project distinguishes pending edits and saves only on request')
    page.locator('[data-kit-plan="c"]').click();page.locator('#workflow-create-kit').click();page.wait_for_function('__qa.editor.current==="proyecto-c/main.c"');assert (ws/'proyecto-c/main.h').is_file() and (ws/'proyecto-c/CMakeLists.txt').is_file();results.append('reviewed C scaffold with header and CMake')
    page.evaluate('__qa.openFile("main.py")');page.wait_for_function('__qa.editor.current==="main.py"');page.evaluate('__qa.desktop.handle("project-workflows")');page.locator('[data-workflow-action="run"]').click();page.locator('#workflow-run-plan').click();page.wait_for_function('__qa.platform.page!=="workflows"');page.wait_for_timeout(1000);assert app.features.workflows.history(app.workspace)[-1]['state']=='passed';results.append('reviewed Python execution and receipt')
    page.evaluate('__qa.desktop.handle("melody-evidence")');page.locator('#workflow-goal').fill('Explica el resultado real');page.locator('#workflow-send-evidence').click();value=page.locator('#ai-input').input_value();assert 'Explica el resultado real' in value and '42' in value and 'passed' in value;assert page.locator('#assistant-panel').is_visible();results.append('Melody evidence stays in docked panel without external request')
    page.evaluate('__qa.desktop.handle("foundation")');page.locator('#lab-tab-machines').click();page.locator('[data-media-import]').wait_for();assert page.locator('.machine-library').is_visible();page.locator('.machine-library details summary').click();page.screenshot(path=str(out/'machine-library.png'));results.append('machine library and OS catalog')
    assert not errors,errors;browser.close()
  finally:server.shutdown();server.server_close();app.features.shutdown();app.runner.shutdown()
 (out/'results.json').write_text(json.dumps({'passed':results,'count':len(results)},indent=2),'utf-8');print(json.dumps({'count':len(results),'passed':results}),flush=True)
if __name__=='__main__':main()
